#!/usr/bin/env bash
# Build Flight Radar.apk from the web assets + the Java sources in this folder.
#
# Unlike a normal Android build this needs **no aapt**: the binary
# AndroidManifest.xml is generated by mkmanifest.js (hand-written AXML), and the
# .apk is zipped by pack.js (pure Node). That makes it buildable on machines
# where only a JDK and d8 are available.
#
# Requirements
#   - JDK 17 (javac, java, keytool on PATH)
#   - Android SDK build-tools for d8 + apksigner, or D8_JAR / APKSIGNER_JAR set
#   - android.jar (platform classes) for javac and d8 --lib
#   - aapt (optional but recommended: real resources + launcher icon).
#     Without it the hand-written AXML path is used and the APK has no icon.
#
# Usage
#   ANDROID_HOME=$HOME/Android/Sdk bash android/build.sh
#   ANDROID_JAR=/path/to/android.jar D8_JAR=/path/to/d8.jar \
#     APKSIGNER_JAR=/path/to/apksigner.jar bash android/build.sh
set -euo pipefail
cd "$(dirname "$0")"

OUT="$PWD/build"
WWW_IN="../public"
APP_ID="com.example.flightradar"          # change together with mkmanifest.js
KEYSTORE="${FR_KEYSTORE:-$PWD/keystore/release.jks}"
KS_ALIAS="${FR_KS_ALIAS:-flightradar}"
KS_PASS="${FR_KS_PASS:-}"

say() { printf '\n== %s\n' "$*"; }

# ---------------------------------------------------------------- toolchain
SDK="${ANDROID_HOME:-${ANDROID_SDK_ROOT:-}}"
pick_jar() { # $1 = jar filename, echo path to build-tools copy
  [ -n "$SDK" ] || return 1
  ls -1d "$SDK"/build-tools/*/lib/"$1" 2>/dev/null | sort -V | tail -1
}
if [ -z "${ANDROID_JAR:-}" ]; then
  if [ -n "$SDK" ]; then
    ANDROID_JAR=$(ls -1 "$SDK"/platforms/android-*/android.jar 2>/dev/null | sort -V | tail -1)
  fi
fi
if [ -z "${ANDROID_JAR:-}" ] || [ ! -f "$ANDROID_JAR" ]; then
  echo "android.jar not found. Set ANDROID_JAR=/path/to/android.jar" >&2
  exit 1
fi
AAPT="${AAPT:-$(command -v aapt || true)}"
# aapt 需要带资源表的 framework：优先用系统的 framework-res.apk，
# 因为 SDK 里的 android.jar 通常只有 class stub、没有 resources.arsc。
FRAMEWORK="${FR_FRAMEWORK:-}"
if [ -z "$FRAMEWORK" ]; then
  if [ -f /system/framework/framework-res.apk ]; then FRAMEWORK=/system/framework/framework-res.apk; else FRAMEWORK="$ANDROID_JAR"; fi
fi
D8_JAR="${D8_JAR:-$(pick_jar d8.jar || true)}"
APKSIGNER_JAR="${APKSIGNER_JAR:-$(pick_jar apksigner.jar || true)}"

say "1/6 sync web assets -> build/assets/www"
rm -rf "$OUT"; mkdir -p "$OUT/assets/www"
cp "$WWW_IN"/index.html "$WWW_IN"/app.js "$WWW_IN"/providers.js "$WWW_IN"/style.css "$OUT/assets/www/"

say "2/6 manifest"
if [ -n "$AAPT" ]; then
  echo "aapt: $AAPT (resources + launcher icon enabled)"
else
  echo "aapt not found -> hand-written binary manifest, no launcher icon" >&2
  node mkmanifest.js "$OUT/AndroidManifest.xml"
  node dumpmanifest.js "$OUT/AndroidManifest.xml" | head -4
fi

say "3/6 javac"
mkdir -p "$OUT/classes"
javac -source 11 -target 11 -nowarn -cp "$ANDROID_JAR" -d "$OUT/classes" \
  src/"${APP_ID//.//}"/MainActivity.java src/"${APP_ID//.//}"/AssetServer.java 2>&1 \
  | grep -v "system modules path" || true
test -f "$OUT/classes/${APP_ID//.//}/MainActivity.class"

say "4/6 d8 (dex)"
mkdir -p "$OUT/dex"
CLASSES=$(ls "$OUT/classes/${APP_ID//.//}"/*.class)
if command -v d8 >/dev/null 2>&1; then
  d8 --min-api 24 --lib "$ANDROID_JAR" --output "$OUT/dex" $CLASSES
elif [ -n "$D8_JAR" ] && [ -f "$D8_JAR" ]; then
  java -cp "$D8_JAR" com.android.tools.r8.D8 --min-api 24 --lib "$ANDROID_JAR" --output "$OUT/dex" $CLASSES
else
  echo "d8 not found: install Android SDK build-tools or set D8_JAR" >&2
  exit 1
fi
mv "$OUT/dex/classes.dex" "$OUT/classes.dex"

say "5/6 package"
if [ -n "$AAPT" ]; then
  "$AAPT" package -f -M AndroidManifest.xml -S res -A "$OUT/assets" \
    -I "$FRAMEWORK" -F "$OUT/flightradar-unsigned.apk"
  ( cd "$OUT" && "$AAPT" add flightradar-unsigned.apk classes.dex )
else
  node pack.js "$OUT/flightradar-unsigned.apk" --root "$OUT"
fi
[ -n "$AAPT" ] && { "$AAPT" list "$OUT/flightradar-unsigned.apk" 2>/dev/null | head -6 || true; }

say "6/6 sign"
mkdir -p "$(dirname "$KEYSTORE")"
if [ ! -f "$KEYSTORE" ]; then
  if [ -z "$KS_PASS" ]; then
    KS_PASS=$(head -c 24 /dev/urandom | base64 | tr -dc 'A-Za-z0-9' | head -c 20)
    printf '%s' "$KS_PASS" > "$KEYSTORE.pass"
    echo "generated a debug keystore: $KEYSTORE"
    echo "password stored in $KEYSTORE.pass (add both to .gitignore)"
  fi
  keytool -genkeypair -keystore "$KEYSTORE" -storetype PKCS12 -alias "$KS_ALIAS" \
    -storepass "$KS_PASS" -keypass "$KS_PASS" -keyalg RSA -keysize 2048 -validity 10950 \
    -dname "CN=Flight Radar, O=flight-radar" >/dev/null 2>&1
elif [ -z "$KS_PASS" ] && [ -f "$KEYSTORE.pass" ]; then
  KS_PASS=$(cat "$KEYSTORE.pass")
fi
[ -n "$KS_PASS" ] || { echo "set FR_KS_PASS for keystore $KEYSTORE" >&2; exit 1; }

if command -v apksigner >/dev/null 2>&1; then
  apksigner sign --ks "$KEYSTORE" --ks-key-alias "$KS_ALIAS" \
    --ks-pass "pass:$KS_PASS" --key-pass "pass:$KS_PASS" \
    --out "$OUT/flightradar.apk" "$OUT/flightradar-unsigned.apk"
elif [ -n "$APKSIGNER_JAR" ] && [ -f "$APKSIGNER_JAR" ]; then
  java -jar "$APKSIGNER_JAR" sign --ks "$KEYSTORE" --ks-key-alias "$KS_ALIAS" \
    --ks-pass "pass:$KS_PASS" --key-pass "pass:$KS_PASS" \
    --out "$OUT/flightradar.apk" "$OUT/flightradar-unsigned.apk"
else
  echo "apksigner not found; unsigned apk kept at $OUT/flightradar-unsigned.apk" >&2
  exit 1
fi
rm -f "$OUT/flightradar-unsigned.apk" "$OUT/flightradar-unsigned.apk.idsig"

ls -l "$OUT/flightradar.apk"
echo "== done: $OUT/flightradar.apk"
